// TextToVideo.js
import React, { useState } from "react";
import Input from "../components/elements/Input";
import classNames from "classnames";

const TextToVideo = () => {
    const [promptInput, setPromptInput] = useState("");
    const [artistInput, setArtistInput] = useState("");
    const [titleInput, setTitleInput] = useState("");
    const [isGenerating, setIsGenerating] = useState(false);
    const [videoUrl, setVideoUrl] = useState("");

    const handleGenerate = async () => {
        setIsGenerating(true);

        try {
            const response = await fetch("http://pve-dungeon.tplinkdns.com:4003/generate", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({ 
                    title: titleInput,
                    artist: artistInput,
                    prompt: promptInput
                }),
            });

            if (!response.ok) {
                throw new Error(`Server error: ${response.statusText}`);
            }

            const data = await response.json();
            setVideoUrl(data.videoUrl); // Assuming the API returns a JSON object with `videoUrl`
        } catch (error) {
            console.error("Error generating video:", error);
            alert("Failed to generate video. Please try again later. Sharing a pre-generated video instead.");
            setVideoUrl(require("../assets/videos/J._Cole_GOMD_cosine_final_video_30fps.mp4"));
        } finally {
            setIsGenerating(false);
        }
    };

    const outerClasses = classNames(
        "form-group", "center-content-mobile", "center-content", "section"
    );

    const formClasses = classNames(
        "form-input"
    );

    const buttonClasses = classNames(
        "button-primary", "button", "form-button"
    );

    return (
        <form className={outerClasses}>
            <div className="container-sm">
                <h1>Music Video Generator (MOVA)</h1>
                <Input
                    placeholder="Enter the song title here..."
                    value={titleInput}
                    onChange={(e) => setTitleInput(e.target.value)}
                    className={formClasses}
                />
                <Input
                    placeholder="Enter the artist here..."
                    value={artistInput}
                    onChange={(e) => setArtistInput(e.target.value)}
                    className={formClasses}
                />
                <Input
                    placeholder="Enter your style prompt here..."
                    value={promptInput}
                    onChange={(e) => setPromptInput(e.target.value)}
                    className={formClasses}
                />

                <div className="button-group">
                    <button
                        onClick={handleGenerate}
                        disabled={isGenerating}
                        className={buttonClasses}
                    >
                        {isGenerating ? "Generating..." : "Generate Video"}
                    </button>
                </div>
                
                {videoUrl && (
                    <div className="video-container">
                        <h2>Generated Video</h2>
                        <video controls className="video">
                            <source src={videoUrl} type="video/mp4" />
                        </video>
                    </div>
                )}
            </div>
        </form>
    );
};


export default TextToVideo;
